create extension if not exists pgcrypto;
create table if not exists public.teams(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,created_at timestamptz default now());
create table if not exists public.players(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.teams(id) on delete cascade,name text not null,jersey_number integer not null,created_at timestamptz default now());
create table if not exists public.games(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.teams(id) on delete cascade,opponent text not null,game_date date not null default current_date,team_score integer not null default 0,opponent_score integer not null default 0,notes text,created_at timestamptz default now());
create table if not exists public.game_player_stats(id uuid primary key default gen_random_uuid(),game_id uuid not null references public.games(id) on delete cascade,player_id uuid not null references public.players(id) on delete cascade,points_1 integer not null default 0,points_2 integer not null default 0,points_3 integer not null default 0,fouls integer not null default 0 check(fouls between 0 and 5),sub_off integer not null default 0,unique(game_id,player_id));
create table if not exists public.drills(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,minutes integer not null check(minutes>0),created_at timestamptz default now());
alter table public.teams enable row level security;alter table public.players enable row level security;alter table public.games enable row level security;alter table public.game_player_stats enable row level security;alter table public.drills enable row level security;
create or replace function public.my_team(tid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.teams where id=tid and user_id=auth.uid())$$;
create or replace function public.my_player(pid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.players p join public.teams t on t.id=p.team_id where p.id=pid and t.user_id=auth.uid())$$;
create or replace function public.my_game(gid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.games g join public.teams t on t.id=g.team_id where g.id=gid and t.user_id=auth.uid())$$;
create policy "teams own" on public.teams for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "players own team" on public.players for all using(public.my_team(team_id)) with check(public.my_team(team_id));
create policy "games own team" on public.games for all using(public.my_team(team_id)) with check(public.my_team(team_id));
create policy "stats own" on public.game_player_stats for all using(public.my_game(game_id) and public.my_player(player_id)) with check(public.my_game(game_id) and public.my_player(player_id));
create policy "drills own" on public.drills for all using(user_id=auth.uid()) with check(user_id=auth.uid());